import {createGroupRopeModel} from './rope-model.js';
import {createRopeSession} from './rope-session.js';
import * as THREE from 'three';
import {createSquareModel,exerciseCueActive} from './model.js';
import {createSquareSession} from './session.js';
import {createSquareView,fitSquareCamera} from './view.js';
const CHOICES=`<div class="square-choices"><p>넓은 광장에서 친구들과 천천히 움직여요. 아무것도 누르지 않아도 함께할 수 있어요.</p><h3>친구들과 체조</h3><button id="square-calm">편하게 함께하기</button><button id="square-timed">박자 맞추기</button><h3>단체 줄넘기</h3><button id="square-rope-calm">편하게 함께 뛰기</button><button id="square-rope-timed">직접 박자에 맞춰 점프</button><button id="square-leave">조용한 광장으로</button></div>`;
const BODY=`<div class="square-layout"><div id="square-court" class="square-court" tabindex="0" role="img" aria-label="광장에서 도름이와 세 친구가 함께 체조해요"></div><section class="square-panel"><p id="square-status" role="status" aria-live="polite"></p><p id="square-hint">자기 속도로 편안하게 함께해요</p><div class="square-actions"><button id="square-start" hidden>천천히 시작하기</button><button id="square-tap" hidden disabled>맞춰요 · Space</button><button id="square-next" hidden>다음 바퀴 준비</button><button id="square-pause" hidden>잠깐 쉬기</button><button id="square-leave">조용한 광장으로</button></div></section></div>`;
export function createSquareController({ui,stage,getView,getActors,getRoom,getWorld,isAllowed=()=>true,beforeStart=()=>{},onActive=()=>{},resolveReturn=p=>p,getQuality=()=>'high',reduced=false,doc=globalThis.document,win=globalThis.window,sessionFactory=null,viewFactory=createSquareView,fitCamera=fitSquareCamera}){
 const camera=new THREE.OrthographicCamera(-1,1,1,-1,.01,300),$=id=>doc.querySelector('#'+id);let live=null,chooser=null,generation=0;
 const current=s=>getRoom()==='courtyard'&&getView()===s.source;
 function listen(owner,n,t,fn){if(n){n.addEventListener(t,fn);owner.listeners.push([n,t,fn]);}}
 function clear(){if(live){live.key=null;live.pointer=null;}}
 function render(){
  if(!live)return;const s=live.model.snapshot(),rope=s.activity==='rope';
  let status=s.paused?'잠깐 쉬어요. 계속하기를 누르면 이어가요':s.phase==='loading'?'친구들이 준비하고 있어요':s.phase==='gathering'?'친구들이 천천히 모이고 있어요':s.phase==='ready'?'준비되면 함께 시작해요':s.phase==='countdown'?(s.mode==='calm'?'숨을 고르고, 천천히':String(Math.ceil(s.countdown))):null;
  if(!status)status=rope?(s.phase==='rest'||s.phase==='settling'||s.phase==='result'?s.feedback:s.mode==='calm'?'친구들과 가볍게 함께 뛰어요':`줄이 돌아요 · ${s.turn+1}번째 바퀴`):s.phase==='result'?(s.mode==='calm'?'함께 편안하게 움직였어요':s.feedback):({forward:'두 팔을 앞으로',raise:'작게 기지개',step:'한 발씩 가볍게',open:'두 팔을 편안하게'}[s.gesture]);
  $('square-status').textContent=status;$('square-start').hidden=s.phase!=='ready';$('square-pause').hidden=!['gathering','countdown','playing','settling'].includes(s.phase);$('square-pause').textContent=s.paused?'계속하기':'잠깐 쉬기';$('square-next').hidden=!rope||s.phase!=='rest';$('square-next').textContent=s.completed>=12?'편안하게 마무리':'다음 바퀴 준비';$('square-tap').hidden=s.mode!=='timed'||s.phase!=='playing';$('square-tap').disabled=rope?!s.canJump:s.paused||s.phase!=='playing';$('square-tap').textContent=rope?'점프 · Space':exerciseCueActive(s.elapsed)?'함께 · 맞춰요':'맞춰요 · Space';
  $('square-hint').textContent=rope?(s.mode==='calm'?'누르지 않아도 도름이가 함께 뛰어요':s.phase==='playing'&&s.nextPeriod<s.period?'다음 바퀴부터 줄이 조금 빨라져요':'Space 또는 큰 버튼으로 가볍게 점프해요'):s.mode==='calm'?'누르지 않아도 함께 움직여요':s.phase==='playing'?(s.feedback||'친구들의 박자에 맞춰 한 번씩 눌러요'):'점수나 보상은 저장하지 않아요';
 }
 function clean(token,{restore=true}={}){if(!live||live.token!==token||live.closing)return;const old=live;old.closing=true;clear();for(const[n,t,f]of old.listeners)n.removeEventListener(t,f);old.observer?.disconnect();old.model.dispose();old.view?.dispose();try{old.session?.dispose({restore:restore&&current(old)});}finally{live=null;generation++;stage.classList.remove('square-open');doc.body?.classList.remove('square-open');onActive(false,{current:current(old)});}}
 function cancel(options){if(!chooser&&!live)return;if(chooser){const c=chooser;chooser=null;for(const[n,t,f]of c.listeners)n.removeEventListener(t,f);generation++;}if(live)clean(live.token,options);ui.close();}
 function pause(){if(!live)return;clear();live.model.pause();render();}
 function begin(mode,kind='exercise'){if(!isAllowed()||doc.hidden||getRoom()!=='courtyard')return false;const source=getView();if(!source?.root)return false;beforeStart();if(!isAllowed()||getView()!==source)return false;const token=++generation;return ui.workshop(kind==='rope'?'친구들과 단체 줄넘기':'친구들과 광장 체조',kind==='rope'?BODY.replace('함께 체조해요','함께 줄넘기를 해요'):BODY,()=>{
  const owner={token,source,kind,listeners:[],model:kind==='rope'?createGroupRopeModel({mode}):createSquareModel({mode}),session:null,view:null,key:null,keyClick:null,pointer:null,fitKey:''};live=owner;
  const valid=()=>live===owner&&generation===token;
  try{onActive(true,{current:true});owner.session=(sessionFactory??(kind==='rope'?createRopeSession:createSquareSession))({activity:kind,view:source,...getActors(),world:getWorld(),isCurrent:()=>valid()&&current(owner),resolveReturn,getQuality});owner.view=kind==='rope'?null:viewFactory(source.root);stage.classList.add('square-open');doc.body?.classList.add('square-open');
   const click=(id,fn)=>listen(owner,$(id),'click',e=>{if(!valid())return;e.preventDefault();fn(e);});click('square-leave',()=>cancel());click('square-next',()=>{clear();owner.model.continue?.();render();$('square-court').focus();});click('square-start',()=>{clear();owner.model.start();render();$('square-court').focus();});click('square-pause',()=>{if(doc.hidden)return;clear();if(owner.model.snapshot().paused)owner.model.resume();else owner.model.pause();render();});
   const tap=$('square-tap');listen(owner,tap,'pointerdown',e=>{if(!valid()||e.button!==0)return;e.preventDefault();owner.keyClick=null;if(e.isPrimary===false||owner.pointer){owner.pointer=null;return;}owner.pointer={id:e.pointerId,x:e.clientX??0,y:e.clientY??0,cancelled:false};tap.setPointerCapture?.(e.pointerId);});listen(owner,tap,'pointermove',e=>{const p=owner.pointer;if(p?.id===e.pointerId&&Math.hypot((e.clientX??p.x)-p.x,(e.clientY??p.y)-p.y)>12)p.cancelled=true;});for(const t of['pointerup','pointercancel','lostpointercapture'])listen(owner,tap,t,e=>{const p=owner.pointer;if(p?.id!==e.pointerId)return;owner.pointer=null;if(valid()&&t==='pointerup'&&!p.cancelled){owner.model.tap();render();}});click('square-tap',e=>{if(e.detail===0&&!owner.key){const duplicate=owner.keyClick&&Number.isFinite(e.timeStamp)&&Number.isFinite(owner.keyClick.stamp)&&e.timeStamp>=owner.keyClick.stamp&&e.timeStamp-owner.keyClick.stamp<80;owner.keyClick=null;if(!duplicate)owner.model.tap();render();}});
   listen(owner,doc,'keydown',e=>{if(!valid())return;if(e.code==='Escape'){e.preventDefault();cancel();return;}if(!['Space','Enter'].includes(e.code)||e.isComposing||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName)||e.target?.isContentEditable||e.code==='Enter'&&e.target?.id!=='square-tap'||e.target?.tagName==='BUTTON'&&e.target.id!=='square-tap')return;e.preventDefault();if(e.repeat||owner.key)return;owner.key=e.code;owner.keyClick=e.target?.id==='square-tap'?{code:e.code,stamp:e.timeStamp}:null;owner.model.tap();render();});listen(owner,doc,'keyup',e=>{if(e.code===owner.key)owner.key=null;if(owner.keyClick?.code===e.code)owner.keyClick.stamp=e.timeStamp;});listen(owner,win,'blur',pause);listen(owner,doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(owner,win,'pagehide',()=>cancel({restore:false}));const resize=()=>{clear();owner.fitKey='';};listen(owner,win,'resize',resize);if(win.visualViewport)listen(owner,win.visualViewport,'resize',resize);
   owner.session.ready.then(ok=>{if(!valid())return;if(!ok){cancel();ui.toast('친구들이 아직 준비되지 않았어요. 원할 때 다시 불러 주세요');return;}owner.model.loaded();owner.fitKey='';if(doc.hidden)pause();render();});render();$('square-court').focus();return()=>clean(token);
  }catch{clean(token);ui.close();ui.toast('광장을 준비하지 못했어요. 원할 때 다시 열어 주세요');}
 },{kind:'square-workshop',closeLabel:'조용한 광장으로'});}
 function open(){if(live||chooser||!isAllowed()||doc.hidden||getRoom()!=='courtyard')return false;const token=++generation;return ui.workshop('광장에서 함께하기',CHOICES,()=>{const owner={listeners:[],token};chooser=owner;for(const [choice,mode,kind]of[['calm','calm','exercise'],['timed','timed','exercise'],['rope-calm','calm','rope'],['rope-timed','timed','rope']])listen(owner,$('square-'+choice),'click',()=>{if(chooser!==owner)return;const next=()=>{if(generation===token)begin(mode,kind);};if(ui.switchTo)ui.switchTo(next);else{ui.close();next();}});listen(owner,$('square-leave'),'click',()=>cancel());return()=>{if(chooser!==owner)return;chooser=null;for(const[n,t,f]of owner.listeners)n.removeEventListener(t,f);};},{kind:'square-chooser',closeLabel:'조용한 광장으로'});}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const box=$('square-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,box.left-base.left),y=Math.max(0,box.top-base.top),r={x,y,width:Math.max(1,Math.min(box.width,width-x)),height:Math.max(1,Math.min(box.height,height-y))},key=[r.width,r.height,live.session?.gathered,live.kind].join('|');if(key!==live.fitKey){fitCamera(camera,live.source.root,r,live.session?.actors??[],{gathered:live.session?.gathered,activity:live.kind});live.fitKey=key;}return r;}
 return{open,cancel,close:cancel,pause,camera,viewport,tick(dt){if(!live)return;if(!current(live)){cancel({restore:false});return;}const owner=live;owner.session.advance(dt,owner.model.snapshot(),reduced);if(!owner.session.active){cancel();return;}if(owner.session.gathered&&owner.model.snapshot().phase==='gathering'){if(owner.kind==='rope')owner.model.bindPhysics(owner.session.physics);owner.model.gathered();}owner.model.advance(dt);owner.session.sync?.(owner.model.snapshot());render();},get active(){return!!live;},get sampleEligible(){return!!live&&!live.model.snapshot().paused&&['gathering','countdown','playing','settling'].includes(live.model.snapshot().phase);},snapshot:()=>live?.model.snapshot()??null};
}
